containerWindowType = {
		name = "capture_scientist_scientist_roster_window"
		animation_time = 300
		size = { width=540 height=640 }
		position = { x = 540 y = 80 }
		show_sound = open_sub_window
		moveable = yes
		click_to_front = yes

		background = {
			name = "capture_scientist_Background"
			spriteType = "GFX_tiled_plain_bg"
		}
		
		containerWindowType = {
			name = "capture_scientist_bottom_bar"
			position = { x = 0 y = 603 }
			size = {width = 540 height = 40}
			
			background = {
				name = "capture_scientist_Background"
				spriteType = "GFX_tiled_window"
			}
		}

		instantTextboxType = {
			name = "capture_scientist_title_text"
			text = "Scientists"
			position = { x = 0 y = 10 }
			font = "hoi_20b"
			maxWidth = 510
			maxHeight = 20
			format = center
		}

		instantTextboxType = {
			name = "capture_scientist_instructions_text"
			text = "Recruit specialists for research facilities."
			position = { x = 0 y = 24 }
			font = "hoi_18b"
			maxWidth = 510
			maxHeight = 20
			format = center
		}

		iconType = {
			name = "capture_scientist_scientist_text_search_bg"
			spriteType = "GFX_FOCUS_FILTER_FIND_BG"
			position = { x = 00 y = 50 }
			tooltip = SCIENTIST_ROSTER_SEARCH_FILTER_TT
		}
		editBoxType = {
			name = "capture_scientist_scientist_text_search"
			position = { x = 42 y = 60 }
			size = {x=150 y=20}
			#textureFile = ""
			font = "hoi_20b"
			borderSize = { x = 0 y = 0 }
			text = SCIENTIST_ROSTER_SEARCH_FILTER_TEXT
			tooltip = SCIENTIST_ROSTER_SEARCH_FILTER_TT
		}

		ButtonType = {
			name = "capture_scientist_sort_name"
			position = {x=199 y=56}
			spriteType = "GFX_sort_up_down_button_83x29"
			buttonText = UNIT_LEADER_NAME_SORT
			buttonFont = "hoi_16mbs"
			clicksound = click_scroll
			frame = 1
			bound_tooltip = {
				localization_key = SCIENTIST_ROSTER_SORT_BUTTON_TOOLTIP
				REASON = SCIENTIST_ROSTER_SORT_BY_NAME_REASON
			}
		}

		iconType = {
			name = "capture_scientist_sort_name_arrow"
			position = { x = 290 y = 46 }
			spriteType = "GFX_division_list_column_button"
			alwaystransparent = yes
			hide = yes
		}

		gridBoxType = {
			# contains "specialization_sort_entry"
			name = "capture_scientist_sort_specialization_box"
			position = { x = 320 y = 40 }
			size = { width = 200 height = 40 }
			slotsize = { width = 30 height = 40 }
			format = "UPPER_LEFT"
		}


		buttonType = {
			name = "capture_scientist_close_button"
			position = { x = -38 y = 4 }
			quadTextureSprite = "GFX_closebutton"
			buttonFont = "Main_14_black"
			shortcut = "ESCAPE"
			Orientation = "UPPER_RIGHT"
			clicksound = click_close
			pdx_tooltip = "CLOSE"
		}

		buttonType = {
			name = "capture_scientist_recruit_scientist_button"
			position = { x = 145 y = 590 }
			quadTextureSprite = "GFX_button_261x34"
			buttonFont = "hoi_18mbs"
			buttonText = "RECRUIT_SCIENTIST_BUTTON"
			clicksound = click_default
		}

		containerWindowType = {
			name = "capture_scientist_scientists"
			position = { x = 0 y = 85 }
			size = { width=540 height=505 }
			margin = { top = 4 bottom = 12}

			background = {
				name = "capture_scientist_Background"
				spriteType = "GFX_tiled_window2_1b_border"
			}

			background = {
				name = "capture_scientist_Background"
				quadTextureSprite = "GFX_tiled_generic_overlay_bg1_small"
				position = { x = -1 y = 0 }
			}

			containerWindowType = {
				name = "capture_scientist_scientist_list_container"
				position = { x = 15 y = 9 }
				size = { width = 100%% height = 478 }
				verticalScrollbar = "right_vertical_slider"
				scroll_wheel_factor = 98
				smooth_scrolling = yes

				background = {
					name = "capture_scientist_Background"
					spriteType = "GFX_tiled_window_transparent"
				}

				gridBoxType = {
					# contains scientist_item
					name = "capture_scientist_scientist_list"
					size = { width = 100%% height = 100%% }
					slotsize = { width = 515 height = 100} # Ändra här :D
					max_slots_horizontal = 1
					format = "UPPER_LEFT"
				}
			}
		}
	}

