capture_scientist_roster = {
		context_type = player_context
		window_name = capture_scientist_scientist_roster_window
		visible = { always = no }
		dynamic_lists = {
			capture_scientist_scientist_list = {
				array = capture_scientists
				entry_container = capture_scientist_scientist_item
			}
			capture_scientist_skill_levels = {
				array = capture_scientist_skill
				entry_container = capture_scientist_skill_level_entry
			}
		}
	}
